import * as react from 'react';
import react__default from 'react';
import { ComponentApi, ComponentContext, ComponentNode, SurfaceModel, ResolveA2uiProps, InferredComponentApiSchemaType, Signal } from '@a2ui/web_core/v0_9';
import type { ZodType } from 'zod';
import { WebComponentImplementation } from '@a2ui/web_core/v0_9/universal';
import { MarkdownRenderer } from '@a2ui/web_core';

/**
 * What a React catalog entry is, and what its rendering entry points receive.
 *
 * These types refer to each other: an implementation's `view` takes
 * `NodeViewProps`, which names a node holding an entry of the same catalog.
 * Keeping them together lets `adapter.tsx` build implementations and
 * `catalog/to_web_component.tsx` host them without importing each other.
 */

/** Renders a resolved child node, or falls back for an unresolved id. */
type NodeBuildChild = (child: ComponentNode<ReactCatalogComponent> | string, basePath?: string) => react__default.ReactNode;
/** What a component implementation's `view` receives from the node surface. */
type NodeViewProps = {
    node: ComponentNode<ReactCatalogComponent>;
    buildChild: NodeBuildChild;
};
/** What a React implementation's `render` receives. */
type ReactRenderProps = {
    context: ComponentContext;
    buildChild: (id: string, basePath?: string) => react__default.ReactNode;
};
/** A catalog entry implemented as a React component. */
interface ReactComponentImplementation<Schema extends ZodType = ZodType> extends ComponentApi<Schema> {
    /** The framework-specific rendering wrapper. */
    render: react__default.FC<ReactRenderProps>;
    /**
     * Renders this component from a resolved `ComponentNode`. Generated by the
     * factories in `adapter.tsx`. When absent, the surface renders through
     * `render`, handing it a `buildChild` that resolves ids through the node
     * layer.
     */
    view?: react__default.FC<NodeViewProps>;
}
/** Any entry a React catalog can hold: a React component or a Web Component. */
type ReactCatalogComponent<Schema extends ZodType = ZodType> = ReactComponentImplementation<Schema> | WebComponentImplementation<Schema>;
/** What the generic binder hands a presentational React component. */
type ReactA2uiComponentProps<T> = {
    props: T;
    buildChild: (id: string, basePath?: string) => react__default.ReactNode;
    context: ComponentContext;
};

/**
 * Surface renderer driven by the node layer.
 *
 * `A2uiSurface` owns one `NodeResolver` for the surface it is given,
 * subscribes to the resolved root node and renders its element; it also
 * portals content into the surface's React hosts that no React-rendered
 * element owns. Everything below the root, including dispatch to each
 * implementation and child reference resolution, lives in `node-view.tsx`.
 */

declare const A2uiSurface: react__default.FC<{
    surface: SurfaceModel<ReactCatalogComponent>;
}>;

/**
 * Creates a React component implementation using the deep generic binder.
 */
declare function createComponentImplementation<Api extends ComponentApi>(api: Api, RenderComponent: react__default.FC<ReactA2uiComponentProps<ResolveA2uiProps<InferredComponentApiSchemaType<Api>>>>): ReactComponentImplementation;
/**
 * Creates a React component implementation that manages its own context bindings (no generic binder).
 */
declare function createBinderlessComponentImplementation(api: ComponentApi, RenderComponent: react__default.FC<ReactRenderProps>): ReactComponentImplementation;

/**
 * The node rendering layer: everything that turns a resolved `ComponentNode`
 * into React output.
 *
 * A node renders as its implementation's custom element (`ChildElement`). For
 * a React implementation that element is a host (`catalog/react_host_element.ts`)
 * and React renders `NodeContent` inside it: the implementation's `view` with
 * the host's node and a `buildChild` that renders child nodes as their own
 * elements. A Web Component renders its own children; the React hosts it
 * creates register with the surface under the nearest React-rendered element
 * above them, and `HostedChildren` beside that element portals `NodeContent`
 * into each. The React tree therefore nests like the DOM, so context, error
 * boundaries and events pass from a component to the components it renders,
 * whether or not a Web Component sits in between. Each factory-made
 * implementation carries a generated `view` (see `adapter.tsx`) that subscribes
 * to its node's props through `useNodeView`, so a data change re-renders
 * exactly the affected component.
 *
 * Every node that reaches a host is resolved: `A2uiSurface` prepares the
 * catalogs, so `impl` is a web component, and the parent only renders nodes
 * that have a `context`.
 */

declare function useSignalValue<T>(signal: Signal<T>): T;

declare const MarkdownContext: react.Context<MarkdownRenderer | undefined>;
declare const useMarkdownRenderer: () => MarkdownRenderer | undefined;

export { A2uiSurface, MarkdownContext, type NodeBuildChild, type NodeViewProps, type ReactA2uiComponentProps, type ReactCatalogComponent, type ReactComponentImplementation, createBinderlessComponentImplementation, createComponentImplementation, useMarkdownRenderer, useSignalValue };
